-- chair-step: inverse of read_lane_v2_b3_28_workbench_heatmap_saves — un-enrolls workbench.heatmap_saves from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'heatmap_saves' and is_active);
select iam.apply_rls('workbench', 'heatmap_saves', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'heatmap_saves' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'heatmap_saves' and is_active));
